const config = $('Configuration').first().json;
const processedIds = new Set();

console.log('=== Fetch Dedup IDs ===');
console.log('Supabase URL: ' + config.SUPABASE_URL);
console.log('Key length: ' + (config.SUPABASE_KEY ? config.SUPABASE_KEY.length : 0));

const h = this.helpers;

const fetchTable = async (table) => {
  try {
    const url = config.SUPABASE_URL + '/rest/v1/' + table + '?select=ticket_id&limit=5000';
    const data = await h.httpRequest({
      method: 'GET',
      url: url,
      headers: {
        apikey: config.SUPABASE_KEY,
        Authorization: 'Bearer ' + config.SUPABASE_KEY,
        Accept: 'application/json'
      },
      json: true
    });
    if (Array.isArray(data)) {
      console.log(table + ': ' + data.length + ' records returned');
      return data;
    }
    console.log(table + ': unexpected response: ' + JSON.stringify(data).substring(0, 200));
    return [];
  } catch(e) {
    console.log(table + ' error: ' + (e.message || e));
    return [];
  }
};

const processed = await fetchTable('tickets_processed');
processed.forEach(row => row.ticket_id && processedIds.add(row.ticket_id));

const gaps = await fetchTable('knowledge_gaps');
gaps.forEach(row => row.ticket_id && processedIds.add(row.ticket_id));

console.log('Total IDs to skip: ' + processedIds.size);
return [{ json: { processed_ids: [...processedIds], count: processedIds.size } }];

const config = $('Configuration').first().json;
const h = this.helpers;

// ── Fetch all 4 KB source files from Supabase ──
const fetchSource = async (name) => {
  const resp = await h.httpRequest({
    method: 'GET',
    url: config.SUPABASE_URL + '/rest/v1/knowledge_sources?name=eq.' + encodeURIComponent(name) + '&select=content',
    headers: { apikey: config.SUPABASE_KEY, Authorization: 'Bearer ' + config.SUPABASE_KEY },
    json: true
  });
  return (Array.isArray(resp) && resp[0]) ? resp[0].content : '';
};

const [faqText, productRefText, engravingCsv, servicingCsv] = await Promise.all([
  fetchSource('faq'),
  fetchSource('product_reference'),
  fetchSource('engraving_rates'),
  fetchSource('servicing_rates')
]);

// ── Fetch unprocessed tickets from Supabase ──
const ticketsResp = await h.httpRequest({
  method: 'GET',
  url: config.SUPABASE_URL + '/rest/v1/tickets_inbox?processed=eq.false&select=*',
  headers: { apikey: config.SUPABASE_KEY, Authorization: 'Bearer ' + config.SUPABASE_KEY },
  json: true
});
const allTickets = Array.isArray(ticketsResp) ? ticketsResp : [];

// ── Fetch learned KB entries (approved additions from WF2) ──
let kbAdditions = [];
try {
  const kbResp = await h.httpRequest({
    method: 'GET',
    url: config.SUPABASE_URL + '/rest/v1/kb_additions?status=eq.approved&order=approved_at.asc',
    headers: { apikey: config.SUPABASE_KEY, Authorization: 'Bearer ' + config.SUPABASE_KEY },
    json: true
  });
  if (Array.isArray(kbResp)) kbAdditions = kbResp;
} catch(e) {
  console.log('KB additions fetch skipped: ' + e.message);
}

// ── Dedup — skip already processed tickets ──
const dedupResult = $('Fetch Dedup IDs').first().json;
const processedIds = new Set(dedupResult.processed_ids || []);

// ── CSV parser (for rate cards stored as CSV text) ──
function parseCSV(csv) {
  const lines = csv.split('\n').filter(l => l.trim());
  const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  return lines.slice(1).map(line => {
    const values = [];
    let cur = '', inQ = false;
    for (const c of line) {
      if (c === '"') { inQ = !inQ; }
      else if (c === ',' && !inQ) { values.push(cur.trim().replace(/^"|"$/g, '')); cur = ''; }
      else { cur += c; }
    }
    values.push(cur.trim().replace(/^"|"$/g, ''));
    const obj = {};
    headers.forEach((h, i) => { obj[h] = values[i] !== undefined ? values[i] : ''; });
    return obj;
  }).filter(r => Object.values(r).some(v => v));
}

const engravingText = parseCSV(engravingCsv)
  .map(r => `  - ${r.service}: SGD ${r.price_sgd} — ${r.notes}`).join('\n');
const servicingText = parseCSV(servicingCsv)
  .map(r => `  - ${r.service_tier}: SGD ${r.price_sgd}, ${r.turnaround_days} days — includes: ${r.includes}`).join('\n');

// ── Assemble Knowledge Base ──
const kbSections = [
  '================================================================',
  'KNOWLEDGE BASE — BOLDR WATCH CS TEAM',
  '================================================================',
  '',
  '--- ⚠️  PRICING CORRECTIONS (HIGHEST PRIORITY — OVERRIDE ALL OTHER SOURCES) ---',
  'The following prices have been verified by the BOLDR team and supersede any',
  'conflicting figures in the FAQ, rate card, or SOP documents.',
  '',
  '  ENGRAVING — Caseback 21 to 40 characters: SGD 35 (CORRECT)',
  '    → FAQ document incorrectly states SGD 40. SOP figure of SGD 35 is authoritative.',
  '    → Flag: [PRICE_CORRECTION_APPLIED] whenever answering this specific query.',
  '',
  '--- SECTION 1: FAQ DOCUMENT ---',
  faqText.trim(),
  '',
  '--- SECTION 2: PRODUCT REFERENCE ---',
  productRefText.trim(),
  '',
  '--- SECTION 3: ENGRAVING RATE CARD ---',
  engravingText,
  '',
  '--- SECTION 4: SERVICING RATE CARD ---',
  servicingText
];

if (kbAdditions.length > 0) {
  kbSections.push('');
  kbSections.push('--- SECTION 5: LEARNED KB ENTRIES (resolved by CS team via WF2) ---');
  kbAdditions.forEach((row, i) => {
    kbSections.push('');
    kbSections.push(`Q${i+1}: ${row.question}`);
    kbSections.push(`A${i+1}: ${row.answer}`);
  });
}
kbSections.push('================================================================');
const KB_CONTEXT = kbSections.join('\n');

// ── Filter and return tickets ──
const limit = Number(config.TICKET_LIMIT) || 0;
const newTickets = allTickets.filter(t => !processedIds.has(t.ticket_id));
const tickets = limit > 0 ? newTickets.slice(0, limit) : newTickets;

if (tickets.length === 0) {
  console.log('No new tickets to process.');
  return [];
}

console.log(`Processing ${tickets.length} tickets | KB: ${kbAdditions.length} learned entries`);

return tickets.map(t => ({
  json: {
    ticket_id:        t.ticket_id,
    date_received:    t.date_received,
    customer_name:    t.customer_name,
    customer_email:   t.customer_email,
    subject:          t.subject,
    message_body:     t.message_body,
    channel:          (t.channel || 'email').toLowerCase().trim(),
    question_type:    t.question_type,
    existing_persona: t.buyer_persona,
    kb_context:       KB_CONTEXT,
    api_key:          config.QWEN_API_KEY,
    model:            config.QWEN_MODEL,
    base_url:         config.QWEN_BASE_URL
  }
}));

const responses = $input.all();
const originals  = $('Build Qwen Request').all();

return responses.map((response, index) => {
  const rawText = response.json.choices?.[0]?.message?.content || '';
  const orig    = originals[index]?.json || {};

  const cleaned = rawText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let result;
  try {
    result = JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { result = JSON.parse(match[0]); }
      catch (e2) { result = null; }
    }
  }

  if (!result) {
    result = {
      answerable:    false,
      confidence:    0,
      theme:         'knowledge_gap',
      buyer_persona: 'unknown',
      draft_reply:   null,
      gap_reason:    'Parse error: ' + rawText.substring(0, 150)
    };
  }

  return {
    json: {
      ticket_id:      orig.ticket_id      || '',
      date_received:  orig.date_received  || '',
      customer_name:  orig.customer_name  || '',
      customer_email: orig.customer_email || '',
      subject:        orig.subject        || '',
      message_body:   orig.message_body   || '',
      channel:        orig.channel        || 'email',
      answerable:     result.answerable,
      confidence:     result.confidence,
      theme:          result.theme,
      buyer_persona:  result.buyer_persona,
      draft_reply:    result.draft_reply,
      gap_reason:     result.gap_reason,
      processed_at:   new Date().toISOString()
    }
  };
});

return $input.all().map(item => {
  const t = item.json;
  return {
    json: {
      ticket_id:         t.ticket_id,
      date_received:     t.date_received,
      customer_name:     t.customer_name,
      customer_email:    t.customer_email,
      subject:           t.subject,
      customer_question: t.message_body,
      channel:           t.channel,
      outcome:           'DRAFT_READY',
      action_required:   'Review and send via ' + (t.channel || 'email'),
      draft_reply:       t.draft_reply,
      buyer_persona:     t.buyer_persona,
      theme:             t.theme,
      confidence:        t.confidence,
      gap_reason:        null,
      processed_at:      t.processed_at
    }
  };
});

return $input.all().map(item => {
  const t = item.json;
  return {
    json: {
      ticket_id:         t.ticket_id,
      date_received:     t.date_received,
      customer_name:     t.customer_name,
      customer_email:    t.customer_email,
      subject:           t.subject,
      customer_question: t.message_body,
      channel:           t.channel,
      outcome:           'KNOWLEDGE_GAP',
      action_required:   'Escalate to CS team — answer not in Knowledge Base',
      draft_reply:       null,
      buyer_persona:     t.buyer_persona,
      theme:             t.theme,
      confidence:        t.confidence,
      gap_reason:        t.gap_reason,
      processed_at:      t.processed_at
    }
  };
});

const items  = $input.all();
const config = $('Configuration').first().json;

const supabaseUrl = config.SUPABASE_URL;
const supabaseKey = config.SUPABASE_KEY;

const allRecords = items.map(i => ({
  ticket_id:         i.json.ticket_id,
  date_received:     i.json.date_received     || null,
  customer_name:     i.json.customer_name,
  customer_email:    i.json.customer_email,
  subject:           i.json.subject,
  customer_question: i.json.customer_question,
  channel:           i.json.channel,
  outcome:           i.json.outcome,
  action_required:   i.json.action_required,
  draft_reply:       i.json.draft_reply       || null,
  buyer_persona:     i.json.buyer_persona,
  theme:             i.json.theme,
  confidence:        i.json.confidence,
  gap_reason:        i.json.gap_reason        || null,
  processed_at:      i.json.processed_at
}));

const gapRecords = items
  .filter(i => i.json.outcome === 'KNOWLEDGE_GAP')
  .map(i => ({
    ticket_id:         i.json.ticket_id,
    date_received:     i.json.date_received   || null,
    customer_name:     i.json.customer_name,
    customer_email:    i.json.customer_email,
    subject:           i.json.subject,
    customer_question: i.json.customer_question,
    channel:           i.json.channel,
    buyer_persona:     i.json.buyer_persona,
    theme:             i.json.theme,
    gap_reason:        i.json.gap_reason      || null,
    status:            'open',
    processed_at:      i.json.processed_at
  }));

const batches = [
  { supabase_url: supabaseUrl, supabase_key: supabaseKey, table: 'tickets_processed', records: allRecords,
    on_conflict: 'ticket_id', prefer: 'resolution=merge-duplicates,return=minimal' }
];

if (gapRecords.length > 0) {
  batches.push({ supabase_url: supabaseUrl, supabase_key: supabaseKey, table: 'knowledge_gaps', records: gapRecords,
    on_conflict: 'ticket_id', prefer: 'resolution=ignore-duplicates,return=minimal' });
}

console.log('Sending ' + allRecords.length + ' records to tickets_processed');
console.log('Sending ' + gapRecords.length + ' records to knowledge_gaps');

return batches.map(b => ({ json: b }));

const items  = $('Merge Results').all();
const drafts = items.filter(i => i.json.outcome === 'DRAFT_READY');
const gaps   = items.filter(i => i.json.outcome === 'KNOWLEDGE_GAP');

console.log('=== BOLDR INTELLIGENCE ENGINE — RUN COMPLETE ===');
console.log('Total processed  : ' + items.length);
console.log('Draft ready      : ' + drafts.length);
console.log('Knowledge gaps   : ' + gaps.length);
console.log('Saved to Supabase: tickets_processed + knowledge_gaps');
console.log('');

if (drafts.length > 0) {
  console.log('--- DRAFT REPLIES ---');
  drafts.forEach(d => {
    const r = d.json;
    console.log('[DRAFT] ' + r.ticket_id + ' | ' + r.channel + ' | ' + r.subject);
    console.log('  Persona: ' + r.buyer_persona + ' | Theme: ' + r.theme + ' | Confidence: ' + r.confidence);
    console.log('  Reply: ' + (r.draft_reply || '').substring(0, 150) + '...');
    console.log('');
  });
}

if (gaps.length > 0) {
  console.log('--- KNOWLEDGE GAPS ---');
  gaps.forEach(g => {
    const r = g.json;
    console.log('[GAP] ' + r.ticket_id + ' | ' + r.channel + ' | ' + r.subject);
    console.log('  Persona: ' + r.buyer_persona + ' | Theme: ' + r.theme);
    console.log('  Reason: ' + r.gap_reason);
    console.log('');
  });
}

return [{
  json: {
    summary: {
      total_processed:   items.length,
      draft_ready:       drafts.length,
      knowledge_gaps:    gaps.length,
      saved_to_supabase: true,
      ran_at:            new Date().toISOString()
    },
    draft_ready: drafts.map(d => d.json),
    gaps:        gaps.map(g => g.json)
  }
}];

const config = $('Configuration').first().json;
const summary = $input.first().json;
const gaps = summary.gaps || [];

console.log('=== Gap Sentiment Analysis ===');
console.log('Gaps to label: ' + gaps.length);

if (gaps.length === 0) {
  console.log('No gaps this run — skipping sentiment analysis');
  return [{ json: { unique_labels: [], config: config } }];
}

const gapList = gaps.map(function(g, i) {
  return (i + 1) + '. ' + (g.customer_question || g.subject || 'Unknown') + ' (theme: ' + (g.theme || 'unknown') + ')';
}).join('\n');

const sys = 'You are a market intelligence analyst for Boldr, a Singapore watch micro-brand. Given a list of customer questions that the CS team could NOT answer (knowledge gaps), extract a SHORT 2-5 word label for each that captures the core marketable topic. Classify each as Boldr Specific (unique to Boldr products or policies) or Market Signal (broader consumer trend across the watch market). Respond ONLY with a valid JSON array, no markdown: [{"index":1,"label":"BPA-Free Straps","classification":"Market Signal"},{"index":2,"label":"Vegan Strap","classification":"Market Signal"}]';

const usr = 'Customer knowledge gaps:\n' + gapList;

let labelData = [];
try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: config.QWEN_BASE_URL,
    headers: { Authorization: 'Bearer ' + config.QWEN_API_KEY, 'Content-Type': 'application/json' },
    body: { model: config.QWEN_MODEL, max_tokens: 400, messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }] },
    json: true
  });
  const rawText = (response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content) || '';
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  try { labelData = JSON.parse(cleaned); }
  catch (e) { const m = cleaned.match(/\[[\s\S]*\]/); if (m) { try { labelData = JSON.parse(m[0]); } catch (e2) {} } }
  console.log('Labels extracted: ' + labelData.length);
} catch (e) { console.log('Qwen label error: ' + (e.message || String(e))); }

const labeled = gaps.map(function(gap, i) {
  const lbl = labelData.find(function(l) { return l.index === i + 1; });
  return {
    gap: gap,
    label: lbl ? lbl.label : (gap.theme || 'general').replace(/_/g, ' '),
    classification: lbl ? (lbl.classification || 'Market Signal') : 'Market Signal'
  };
});

const byLabel = {};
for (const item of labeled) {
  const key = item.label.toLowerCase();
  if (!byLabel[key]) byLabel[key] = { label: item.label, classification: item.classification, questions: [], gap_count: 0 };
  byLabel[key].questions.push(item.gap.customer_question || item.gap.subject || '');
  byLabel[key].gap_count++;
}

const unique_labels = Object.values(byLabel);
console.log('Unique labels after dedup: ' + unique_labels.length);
return [{ json: { unique_labels: unique_labels, config: config } }];

const input = $input.first().json;
const unique_labels = input.unique_labels || [];
const config = input.config;

if (unique_labels.length === 0) {
  console.log('No labels to search — sentiment analysis skipped');
  return [{ json: { sentiment_records: [], config: config } }];
}

const TAVILY_KEY = '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';
const h = this.helpers;

const tavilySearch = async function(query, includeDomains) {
  try {
    return await h.httpRequest({
      method: 'POST',
      url: 'https://api.tavily.com/search',
      headers: { Authorization: 'Bearer ' + TAVILY_KEY, 'Content-Type': 'application/json' },
      body: { query: query, include_domains: includeDomains, search_depth: 'advanced', max_results: 3, include_answer: true },
      json: true
    });
  } catch (e) {
    console.log('Tavily error for "' + query + '": ' + (e.message || String(e)));
    return null;
  }
};

const getTopResult = function(resp) {
  if (!resp || !resp.results || resp.results.length === 0) return { name: 'No results found', url: '', score: 2 };
  const top = resp.results[0];
  let score = 2 + Math.min(4, resp.results.length);
  if (resp.answer && resp.answer.length > 30) score += 2;
  if (top.score && top.score > 0.6) score += 2;
  return { name: top.title || 'Result found', url: top.url || '', score: Math.min(10, Math.max(1, score)) };
};

const sentiment_records = [];

for (const item of unique_labels) {
  const label = item.label;
  const classification = item.classification;
  const questions = item.questions;
  const gap_count = item.gap_count;

  console.log('Searching external sources for: ' + label);
  const searchTerm = label + ' watch';

  const redditResp     = await tavilySearch(searchTerm + ' microbrand', ['reddit.com']);
  const watchuseekResp = await tavilySearch(searchTerm, ['watchuseek.com']);
  const amazonResp     = await tavilySearch(searchTerm + ' strap', ['amazon.com', 'amazon.sg']);

  const reddit     = getTopResult(redditResp);
  const watchuseek = getTopResult(watchuseekResp);
  const amazon     = getTopResult(amazonResp);

  const overallScore = Math.round((reddit.score + watchuseek.score + amazon.score) / 3);
  const sourcesHit = [redditResp, watchuseekResp, amazonResp].filter(function(r) { return r && r.results && r.results.length > 0; }).length;

  sentiment_records.push({
    label: label,
    original_questions: questions,
    gap_count: gap_count,
    classification: classification,
    reddit_name:      reddit.name,
    reddit_url:       reddit.url,
    reddit_score:     reddit.score,
    watchuseek_name:  watchuseek.name,
    watchuseek_url:   watchuseek.url,
    watchuseek_score: watchuseek.score,
    amazon_name:      amazon.name,
    amazon_url:       amazon.url,
    amazon_score:     amazon.score,
    overall_score:    overallScore,
    summary:          label + ': signal in ' + sourcesHit + '/3 sources. ' + classification + '.',
    last_seen_at:     new Date().toISOString()
  });
}

console.log('Tavily searches done: ' + sentiment_records.length + ' records ready');
return [{ json: { sentiment_records: sentiment_records, config: config } }];

const input = $input.first().json;
const sentiment_records = input.sentiment_records || [];
const config = input.config;

if (sentiment_records.length === 0) {
  console.log('No sentiment records to save');
  return [{ json: { saved: 0, errors: 0 } }];
}

const h = this.helpers;
let saved = 0;
let errors = 0;

for (const record of sentiment_records) {
  try {
    await h.httpRequest({
      method: 'POST',
      url: config.SUPABASE_URL + '/rest/v1/gap_sentiment?on_conflict=label',
      headers: {
        apikey: config.SUPABASE_KEY,
        Authorization: 'Bearer ' + config.SUPABASE_KEY,
        'Content-Type': 'application/json',
        Prefer: 'resolution=merge-duplicates,return=minimal'
      },
      body: record,
      json: true
    });
    saved++;
    console.log('Saved: ' + record.label + ' (score: ' + record.overall_score + ')');
  } catch (e) {
    errors++;
    console.log('Error saving "' + record.label + '": ' + (e.message || String(e)));
  }
}

console.log('=== Gap Sentiment Complete: ' + saved + ' saved, ' + errors + ' errors ===');
return [{ json: { saved: saved, errors: errors } }];
